"""Reconcile source requirements and measured production into the one queue.
Run after queue changes to refresh the generated, self-contained HTML view.
"""
from pathlib import Path
import json,re,hashlib,datetime,html
R=Path(__file__).parent
q=json.loads((R/'queue.json').read_text());inv=json.loads((R/'requirements-source.json').read_text())
